import{_ as s,C as i,o as n,c as l,j as t,a,E as d,ag as c}from"./chunks/framework.HG0H2VLS.js";const y=JSON.parse('{"title":"StylePreview","description":"","frontmatter":{},"headers":[],"relativePath":"cc-patterns/style-preview.md","filePath":"cc-patterns/style-preview.md"}'),h={name:"cc-patterns/style-preview.md"},p={id:"stylepreview",tabindex:"-1"};function m(w,e,g,b,v,u){const r=i("Badge"),o=i("ComponentDemo");return n(),l("div",null,[e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"title-stylepreview",tabindex:"-1"},[a("title: StylePreview "),t("a",{class:"header-anchor",href:"#title-stylepreview","aria-label":'Permalink to "title: StylePreview"'},"​")],-1)),t("h1",p,[e[0]||(e[0]=a("StylePreview ",-1)),d(r,{type:"info",text:"Design System"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#stylepreview","aria-label":'Permalink to "StylePreview <Badge type="info" text="Design System" />"'},"​",-1))]),e[5]||(e[5]=t("blockquote",null,[t("p",null,'the "Preview" section first on Design Style / Design Frame View + Edit: the record drawn in its own CSS in a sandboxed iframe, Desktop / Tablet / Mobile (site Breakpoint Profile) via SegmentedControl sm in the RecordSection header, height fitted; Edit fields with data-preview-prop update it live')],-1)),d(o,{src:"/demos/src/cc/patterns/StylePreview/StylePreview.html"}),e[6]||(e[6]=c('<h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Design Style and Design Frame are styling records. v1 opens them with a live sample drawn in the record&#39;s OWN CSS: Design Style View&#39;s resizable <code>DesignTable</code> (<code>AfcDesignCentre/CC/DC_DesignStyle.cfm</code>), and Design Frame&#39;s Preview tab on View and Edit (<code>DC_DesignFrameDef.cfm</code>, <code>DC_DesignFrame.js</code>). In v1 the client CSS is injected into the Control page itself.</p><p>v3: a <strong>&quot;Preview&quot; RecordSection, first in the main column, on View AND Edit of both records</strong> (Mark, 2026-10-29: placement, both screens, width presets, slicer later). The sample renders in a <strong>sandboxed iframe</strong> (<code>sandbox=&quot;allow-same-origin&quot;</code>, so no scripts run in it). The client&#39;s CSS can&#39;t restyle the Control Centre, and the CC&#39;s tokens and theme can&#39;t leak into the preview. The preview stays the site&#39;s own look in CC dark mode, by design: it shows the site.</p><h2 id="variant-×-state-matrix" tabindex="-1">Variant × State Matrix <a class="header-anchor" href="#variant-×-state-matrix" aria-label="Permalink to &quot;Variant × State Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind (<code>data-style-preview</code>)</th><th>Screen</th><th>Width</th><th>Notes</th></tr></thead><tbody><tr><td><code>style</code></td><td>View, Edit</td><td>Desktop / Tablet / Mobile</td><td>v1&#39;s sample verbatim: H1 title; thumbnail + H2 / H3 / H4 + teaser; paragraph with a link and highlight; error panel. v1&#39;s icon row is omitted until the style&#39;s icons are served</td></tr><tr><td><code>frame</code></td><td>View, Edit</td><td>Desktop / Tablet / Mobile</td><td>Frame header + body sample. The border-image slicer (Border Type = Image) is a separate pass</td></tr></tbody></table><p>Width presets: <strong>Desktop</strong> fills the column; <strong>Tablet</strong> and <strong>Mobile</strong> are the site&#39;s Breakpoint Profile widths (<code>data-widths</code>, demo 768px / 375px), centred and capped at the column. On a narrow column (<code>cs-page</code> ≤ 767px) the switch keeps its icons and hides its labels; the labels stay as the accessible names.</p><h2 id="behaviour-stylepreview-js" tabindex="-1">Behaviour (StylePreview.js) <a class="header-anchor" href="#behaviour-stylepreview-js" aria-label="Permalink to &quot;Behaviour (StylePreview.js)&quot;">​</a></h2><ul><li>Builds <code>srcdoc</code> from the kind&#39;s sample and the template CSS; fits the height on load, when images load, on width change and on any column resize (ResizeObserver: the CC column changes width with no window resize).</li><li>Width switch: listens for SegmentedControl&#39;s <code>seg-control:change</code>.</li><li>Edit: <code>input</code> / Select picks on <code>[data-preview-prop]</code> rows set that custom property on the preview&#39;s root (an empty value removes it, falling back to the record&#39;s value).</li><li>Links inside the preview don&#39;t navigate.</li></ul><h2 id="backend-handover-→-recordscreen" tabindex="-1">Backend (HANDOVER → RecordScreen) <a class="header-anchor" href="#backend-handover-→-recordscreen" aria-label="Permalink to &quot;Backend (HANDOVER → RecordScreen)&quot;">​</a></h2><ul><li><code>style-preview-css</code>: the record&#39;s generated CSS per record, plus the Breakpoint Profile widths.</li><li><code>style-preview-live</code>: drive the live preview from unsaved field values.</li><li><code>design-frame-slicer</code> (needs design): Border Type = Image&#39;s slice editor.</li></ul><h2 id="verified-headless-chrome-2026-10-29" tabindex="-1">Verified (headless Chrome, 2026-10-29) <a class="header-anchor" href="#verified-headless-chrome-2026-10-29" aria-label="Permalink to &quot;Verified (headless Chrome, 2026-10-29)&quot;">​</a></h2><p>31 checks pass on DesignStyleView / Edit and DesignFrameView / Edit:</p><ul><li>the preview is the first section, and the iframe is sandboxed;</li><li>v1&#39;s sample text renders, with the client CSS applied inside and isolated outside;</li><li>the height fits exactly, grows at Tablet and shrinks back at Desktop;</li><li>Tablet is 768 and centred, Mobile is 375, both capped at 480;</li><li>live colour, select and number+px fields update the preview, and clearing one falls back;</li><li>no page errors, no overflow, no second scroller.</li></ul><p>Screenshots were checked in light and dark, at 1280 and 480. The demo page (<code>StylePreview.html</code>) was checked at 1280 and 480.</p><h2 id="css-classes" tabindex="-1">CSS Classes <a class="header-anchor" href="#css-classes" aria-label="Permalink to &quot;CSS Classes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>Class</th><th>From</th></tr></thead><tbody><tr><td>Section</td><td><code>.record-section.record-section--preview</code></td><td>RecordSection</td></tr><tr><td>Width switch</td><td><code>.seg-control.style-preview__widths</code> (<code>data-seg-control</code>, values desktop / tablet / mobile)</td><td>SegmentedControl (base)</td></tr><tr><td>Stage</td><td><code>.style-preview</code> (<code>data-style-preview</code>, <code>data-widths</code>, <code>data-thumb</code>)</td><td>new</td></tr><tr><td>Record CSS</td><td><code>&lt;template data-style-preview-css&gt;</code></td><td>new</td></tr><tr><td>Frame</td><td><code>.style-preview__frame</code> (iframe, <code>title=&quot;Preview of &lt;name&gt;&quot;</code>)</td><td>new</td></tr><tr><td>Live field (Edit)</td><td><code>.field-row[data-preview-prop=&quot;--x&quot;][data-preview-unit]</code></td><td>FieldRow + attr</td></tr></tbody></table><h2 id="token-mapping" tabindex="-1">Token Mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>Why</th></tr></thead><tbody><tr><td>Frame border</td><td><code>1px solid --ao-border-secondary</code></td><td>the kit&#39;s card edge (Accordion Separated Cards, datatables)</td></tr><tr><td>Frame radius</td><td><code>--ao-radius-md</code></td><td>same</td></tr><tr><td>Switch spacing</td><td><code>margin-inline-start: auto</code> in the RecordSection header (its own gap)</td><td>no new value</td></tr></tbody></table><p>Inside the iframe: <strong>the client&#39;s CSS only</strong>. Its hex and px values are record data, not DS styling.</p><h2 id="token-gaps" tabindex="-1">Token Gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token Gaps&quot;">​</a></h2><p>None. The preset widths are site data (Breakpoint Profile), not design tokens. The frame height is measured (the sample&#39;s height plus the frame&#39;s border), not a design value.</p><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=4527-43878" target="_blank" rel="noreferrer">Open in Figma</a></p>',23))])}const S=s(h,[["render",m]]);export{y as __pageData,S as default};
